class TestSatisfaction:
    def _make_pref(self, anchor=None, saturation=1.0):
        """Create a minimal concrete subclass for testing."""
        class DummyPref(BaseMotionPreference):
            def get_reward(self, env):
                return 0.5
            @property
            def objects_of_interest(self):
                return set()
        p = DummyPref.__new__(DummyPref)
        BaseMotionPreference.__init__(p)
        p.pref_anchor = anchor
        p.saturation = saturation
        return p

    def test_satisfaction_with_anchor(self):
        p = self._make_pref(anchor=0.8)
        s = p.satisfaction(0.8)
        assert abs(s - 100.0) < 1e-5

    def test_satisfaction_half_anchor(self):
        p = self._make_pref(anchor=1.0)
        s = p.satisfaction(0.5)
        assert abs(s - 50.0) < 1e-5

    def test_satisfaction_clamps_at_100(self):
        p = self._make_pref(anchor=0.5)
        s = p.satisfaction(1.0)
        assert abs(s - 100.0) < 1e-5

    def test_satisfaction_without_anchor(self):
        p = self._make_pref(saturation=0.5)
        s = p.satisfaction(0.5)
        assert abs(s - 100.0) < 1e-5


class TestMappedSatisfaction:
    def _make_pref(self):
        class DummyPref(BaseMotionPreference):
            def get_reward(self, env):
                return 0.0
            @property
            def objects_of_interest(self):
                return set()
        p = DummyPref.__new__(DummyPref)
        BaseMotionPreference.__init__(p)
        p.pref_anchor = 1.0
        return p

    @pytest.mark.parametrize("mean_reward,expected_mapped", [
        (1.0, 1.00),   # 100% satisfaction -> 1.00
        (0.8, 0.75),   # 80% -> 0.75
        (0.5, 0.25),   # 50% -> 0.25
        (0.1, 0.00),   # 10% -> 0.00
    ])
    def test_buckets(self, mean_reward, expected_mapped):
        p = self._make_pref()
        assert p.mapped_satisfaction(mean_reward) == expected_mapped


class _FakeSim:
    """Minimal env.sim stand-in: EE body pose + finger joints + objects."""
    def __init__(self):
        self.pos = {"gripper0_eef": [0, 0, 1.0], "robot0_base": [0, 0, 0.9]}
        self.quat = [1.0, 0.0, 0.0, 0.0]
        self.fingers = [0.04, -0.04]
        self.model = self
        self.data = self
    def body_name2id(self, name):
        return name
    @property
    def body_xpos(self):
        import numpy as np
        return {k: np.asarray(v, float) for k, v in self.pos.items()}
    @property
    def body_xquat(self):
        import numpy as np
        return {"gripper0_eef": np.asarray(self.quat, float)}
    def get_joint_qpos(self, name):
        return self.fingers[0] if name.endswith("1") else self.fingers[1]


class _FakeEnv:
    def __init__(self):
        self.sim = _FakeSim()


def _drive(pref, frames):
    """frames: list of dicts {pos, quat?, grip?, success?}"""
    env = _FakeEnv()
    pref.reset(env)
    for f in frames:
        env.sim.pos["gripper0_eef"] = list(f["pos"])
        env.sim.quat = list(f.get("quat", [1, 0, 0, 0]))
        env.sim.fingers = list(f.get("grip", [0.04, -0.04]))
        pref.get_reward(env)
        if f.get("success"):
            pref.mark_success()
    return pref


def _quat_z(theta):
    import numpy as np
    return [np.cos(theta / 2), 0.0, 0.0, np.sin(theta / 2)]


class TestSpeedStepsUntilSuccess:
    def test_raw_stops_at_success(self):
        from Preference.low_level.speed import SpeedRangePreference
        frames = [{"pos": (0.01 * i, 0, 1)} for i in range(10)]
        frames[6]["success"] = True
        p = _drive(SpeedRangePreference(), frames)
        assert p.final_raw() == 7.0

    def test_raw_is_total_without_success(self):
        from Preference.low_level.speed import SpeedRangePreference
        p = _drive(SpeedRangePreference(), [{"pos": (0, 0, 1)}] * 5)
        assert p.final_raw() == 5.0


class TestAccRangeP95Raw:
    def test_gentle_vs_jerky(self):
        from Preference.low_level.speed import AccRangePreference
        gentle = [{"pos": (0.005 * i, 0, 1)} for i in range(30)]           # constant speed -> acc 0
        jerky = [{"pos": (0.005 * i + (0.02 if i % 2 else 0), 0, 1)} for i in range(30)]
        g = _drive(AccRangePreference(max_acc=0.03), gentle).final_raw()
        j = _drive(AccRangePreference(max_acc=0.03), jerky).final_raw()
        assert g < 1e-9 and j > 0.01

    def test_ignores_post_success_tail(self):
        from Preference.low_level.speed import AccRangePreference
        frames = [{"pos": (0.005 * i, 0, 1)} for i in range(20)]
        frames[19]["success"] = True
        frames += [{"pos": (0.1 * i, 0, 1)} for i in range(5)]     # violent tail
        assert _drive(AccRangePreference(), frames).final_raw() < 1e-9


class TestStraightPathCarrySegment:
    @staticmethod
    def _episode(diagonal: bool):
        # approach (open), grasp, carry to (0.3, 0.3), descend, release
        fr = [{"pos": (0, 0, 1.0)}] * 3
        closed = [0.02, -0.02]
        if diagonal:
            carry = [{"pos": (0.3 * t / 20, 0.3 * t / 20, 1.0 + 0.2 * t / 20), "grip": closed} for t in range(21)]
        else:
            carry = [{"pos": (0, 0, 1.0 + 0.2 * t / 10), "grip": closed} for t in range(11)]
            carry += [{"pos": (0.3 * t / 10, 0.3 * t / 10, 1.2), "grip": closed} for t in range(1, 11)]
        desc = [{"pos": (0.3, 0.3, 1.2 - 0.2 * t / 10), "grip": closed} for t in range(1, 11)]
        tail = [{"pos": (0.3, 0.3, 1.0), "success": True}]
        return fr + carry + desc + tail

    def test_diagonal_is_straight_L_is_not(self):
        from Preference.low_level.trajectory import StraightPathPreference
        d = _drive(StraightPathPreference(), self._episode(True)).final_raw()
        l = _drive(StraightPathPreference(), self._episode(False)).final_raw()
        assert d < 0.02 and l > 0.2


class TestHeightOffsetLateralMax:
    def test_higher_move_gives_larger_raw(self):
        from Preference.low_level.trajectory import HeightOffsetPreference
        def ep(zc):
            return [{"pos": (0.01 * t, 0, zc)} for t in range(30)]
        hi = _drive(HeightOffsetPreference(0.1), ep(1.3)).final_raw()
        lo = _drive(HeightOffsetPreference(-0.05), ep(1.05)).final_raw()
        assert abs(hi - (1.3 - 0.9)) < 1e-6 and abs(lo - (1.05 - 0.9)) < 1e-6


class TestRotationLateralShare:
    def test_rotate_while_moving_vs_in_place(self):
        from Preference.low_level.trajectory import RotationPreference
        moving = [{"pos": (0.005 * i, 0, 1), "quat": _quat_z(0.1 * i)} for i in range(10)]
        in_place = [{"pos": (0, 0, 1), "quat": _quat_z(0.1 * i)} for i in range(10)]
        in_place += [{"pos": (0.005 * i, 0, 1), "quat": _quat_z(0.9)} for i in range(10)]
        assert _drive(RotationPreference(), moving).final_raw() > 0.99
        assert _drive(RotationPreference(), in_place).final_raw() < 0.01

    def test_no_rotation_is_zero(self):
        from Preference.low_level.trajectory import RotationPreference
        assert _drive(RotationPreference(), [{"pos": (0.005 * i, 0, 1)} for i in range(10)]).final_raw() == 0.0


class TestAvoidCarryWindowRaw:
    def _pref(self, dists, grips):
        from Preference.low_level import distance as dist_mod
        p = dist_mod.AvoidToObjectPreference(target_obj="wine_bottle_1", threshold=0.15)
        p.set_task_context([])
        p._reward_func = lambda env, params: 1.0
        state = {"i": 0}
        orig = dist_mod._gripper_object_distance
        dist_mod._gripper_object_distance = lambda env, name: dists[state["i"]]
        try:
            env = _FakeEnv(); p.reset(env)
            for i, (d, g) in enumerate(zip(dists, grips)):
                state["i"] = i
                env.sim.pos["gripper0_eef"] = [0.01 * i, 0, 1.0 + (0.1 if 5 <= i < 25 else 0.0)]
                env.sim.fingers = list(g)
                p.get_reward(env)
        finally:
            dist_mod._gripper_object_distance = orig
        return p

    def test_min_over_carry_window_only(self):
        closed, opened = [0.02, -0.02], [0.04, -0.04]
        grips = [opened] * 5 + [closed] * 20 + [opened] * 5
        dists = [0.05] * 5 + [0.30] * 20 + [0.05] * 5     # close only outside the carry
        p = self._pref(dists, grips)
        assert abs(p.final_raw() - 0.30) < 1e-9

    def test_reset_clears(self):
        p = self._pref([0.2] * 3, [[0.04, -0.04]] * 3)
        p.reset(_FakeEnv())
        assert p.final_raw(0.77) == 0.77
